from collections import Counter,deque
def comps(grid,bg):
    H,W=len(grid),len(grid[0]); seen=set(); out=[]
    for i in range(H):
        for j in range(W):
            if grid[i][j]!=bg and (i,j) not in seen:
                q=deque([(i,j)]); seen.add((i,j)); cells=[]
                while q:
                    r,c=q.popleft(); cells.append((r,c))
                    for dr in(-1,0,1):
                        for dc in(-1,0,1):
                            nr,nc=r+dr,c+dc
                            if 0<=nr<H and 0<=nc<W and (nr,nc) not in seen and grid[nr][nc]!=bg:
                                seen.add((nr,nc)); q.append((nr,nc))
                out.append(cells)
    return out

def transform(grid):
    bg=Counter(v for row in grid for v in row).most_common(1)[0][0]
    cs=comps(grid,bg)
    pat=max(cs,key=len)
    rs=[r for r,c in pat]; cl=[c for r,c in pat]
    top,bot,left,right=min(rs),max(rs),min(cl),max(cl)
    P=[[grid[r][c] for c in range(left,right+1)] for r in range(top,bot+1)]
    h,w=len(P),len(P[0]); ch,cw=(h-1)//2,(w-1)//2
    out=[row[:] for row in grid]
    for cells in cs:
        if cells is pat: continue
        for (r,c) in cells:
            for i in range(h):
                for j in range(w):
                    rr,cc=r-ch+i,c-cw+j
                    if 0<=rr<len(grid) and 0<=cc<len(grid[0]):
                        out[rr][cc]=P[i][j]
    return out

