lib='''"""Reusable grid functions for ARC tasks."""
from collections import Counter, deque

def background(grid):
    """The most common color in the grid."""
    return Counter(v for row in grid for v in row).most_common(1)[0][0]

def components(grid, bg=None):
    """All 8-connected components of non-background cells, as lists of (r, c); bg defaults to the most common color."""
    if bg is None:
        bg = background(grid)
    H, W = len(grid), len(grid[0]); seen = set(); out = []
    for i in range(H):
        for j in range(W):
            if grid[i][j] != bg and (i, j) not in seen:
                q = deque([(i, j)]); seen.add((i, j)); cells = []
                while q:
                    r, c = q.popleft(); cells.append((r, c))
                    for dr in (-1, 0, 1):
                        for dc in (-1, 0, 1):
                            nr, nc = r + dr, c + dc
                            if 0 <= nr < H and 0 <= nc < W and (nr, nc) not in seen and grid[nr][nc] != bg:
                                seen.add((nr, nc)); q.append((nr, nc))
                out.append(cells)
    return out

def bbox_cells(grid, cells):
    """The bounding-box subgrid of grid covering the given (r, c) cells."""
    rs = [r for r, c in cells]; cs = [c for r, c in cells]
    top, bot, left, right = min(rs), max(rs), min(cs), max(cs)
    return [[grid[r][c] for c in range(left, right + 1)] for r in range(top, bot + 1)]

def stamp(grid, pattern, r, c, ch=None, cw=None):
    """Copy pattern onto grid centered at (r, c) (center offset ch, cw defaults to pattern's middle), clipped at the edges."""
    h, w = len(pattern), len(pattern[0])
    if ch is None: ch = (h - 1) // 2
    if cw is None: cw = (w - 1) // 2
    for i in range(h):
        for j in range(w):
            rr, cc = r - ch + i, c - cw + j
            if 0 <= rr < len(grid) and 0 <= cc < len(grid[0]):
                grid[rr][cc] = pattern[i][j]
    return grid
